WITH store_dates AS ( SELECT s.s_store_sk, s.s_store_name, s.s_closed_date_sk, d.d_year AS closed_year, CASE WHEN d.d_year < 2010 THEN 'Pre-2010' WHEN d.d_year BETWEEN 2010 AND 2015 THEN '2010-2015' ELSE 'Post-2015' END AS year_bucket FROM store s JOIN date_dim d ON s.s_closed_date_sk = d.d_date_sk ) SELECT sd.s_store_sk, sd.s_store_name, sd.closed_year, sd.year_bucket, COALESCE(cr.cr_total_return_amt, 0) AS catalog_return_total, COALESCE(wr.wr_total_return_amt, 0) AS web_return_total, (COALESCE(cr.cr_total_return_amt, 0) + COALESCE(wr.wr_total_return_amt, 0)) AS overall_return_total, DENSE_RANK() OVER (PARTITION BY sd.year_bucket ORDER BY (COALESCE(cr.cr_total_return_amt, 0) + COALESCE(wr.wr_total_return_amt, 0)) DESC) AS bucket_rank FROM store_dates sd LEFT JOIN ( SELECT cr_returned_date_sk, SUM(cr_return_amt_inc_tax) AS cr_total_return_amt FROM catalog_returns GROUP BY cr_returned_date_sk ) cr ON cr.cr_returned_date_sk = sd.s_closed_date_sk LEFT JOIN ( SELECT wr_returned_date_sk, SUM(wr_return_amt_inc_tax) AS wr_total_return_amt FROM web_returns GROUP BY wr_returned_date_sk ) wr ON wr.wr_returned_date_sk = sd.s_closed_date_sk ORDER BY sd.year_bucket, bucket_rank LIMIT 20
